var sums = new long[8];          // 64 bytes: neighbors share a cache line
Parallel.For(0, 8, t =>
{
    for (int i = 0; i < 100_000_000; i++)
        sums[t]++;               // no race, yet the line bounces
});

// cure: a local total, one write at the end
Parallel.For(0, 8, t =>
{
    long local = 0;
    for (int i = 0; i < 100_000_000; i++) local++;
    sums[t] = local;
});
